package ru.hive13.server;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import ru.hive13.model.*;
import static ru.hive13.model.Model.*;
import java.nio.file.*;
import java.util.*;
class EngineTest {
    GameEngine e;
    @BeforeEach void init(){e=new GameEngine(WorldFactory.create("REFERENCE_DEMO"));for(var a:e.state.actors){a.connected=true;a.ready=true;}e.start();}
    GameEngine.Result cmd(int slot,String type,Map<String,?> data){return e.command(slot,new Packet(type,UUID.randomUUID().toString(),data));}
    void vote(String... options){for(int i=0;i<3;i++)assertTrue(cmd(i,"VOTE",Map.of("cycle",e.state.cycle,"option",options[i])).accepted());}
    @Test void exactlySixtySecondsAndVotingFreezesWorld(){e.advance(59.95);assertEquals(Phase.ACTION,e.state.phase);e.advance(.05);assertEquals(Phase.VOTING,e.state.phase);double biomass=e.state.rooms.get("B4").biomass,time=e.state.gameTime;e.advance(5);assertEquals(time,e.state.gameTime);assertEquals(biomass,e.state.rooms.get("B4").biomass);}
    @Test void majoritySealsThreeDoorsAndSpendsOnce(){e.advance(60);vote("seal_b4","generator","seal_b4");assertEquals(2,e.state.cycle);assertTrue(e.state.flags.contains("b4_sealed"));assertEquals(10,e.state.supplies.get("parts"));assertTrue(e.state.doors.values().stream().filter(d->d.a.equals("B4")||d.b.equals("B4")).allMatch(d->d.status==DoorStatus.SEALED));e.resolveVote();assertEquals(10,e.state.supplies.get("parts"));}
    @Test void unanimousGeneratorAndTieDeferral(){e.advance(60);vote("generator","generator","generator");assertEquals(5,e.state.supplies.get("fuel"));assertEquals(68,e.state.power);e.state.cycle=3;e.state.flags.add("lina_decided");e.advance(60);vote("sample_goal","seal_b4","surface_goal");assertEquals("defer",e.state.decisions.getLast().optionId);assertEquals(79,e.state.water);}
    @Test void personalConsentCannotBeOverruled(){e.state.creatures.clear();var a=e.state.actor(2);a.roomId="B4";a.x=530;a.y=95;e.advance(60);vote("seal_b4","seal_b4","generator");assertFalse(e.state.flags.contains("b4_sealed"));assertEquals("defer",e.state.decisions.getLast().optionId);}
    @Test void duplicateAndOldCommandsDoNotDoubleSpend(){e.advance(60);var p=new Packet("VOTE","same",Map.of("cycle",1,"option","seal_b4"));assertTrue(e.command(0,p).accepted());assertTrue(e.command(0,p).accepted());assertEquals(1,e.state.ballots.size());cmd(1,"VOTE",Map.of("cycle",1,"option","seal_b4"));cmd(2,"VOTE",Map.of("cycle",1,"option","generator"));assertTrue(e.command(0,p).accepted());assertEquals(10,e.state.supplies.get("parts"));assertFalse(cmd(1,"VOTE",Map.of("cycle",1,"option","generator")).accepted());}
    @Test void nonfiniteAndUnknownCoordinatesAreRejected(){assertFalse(cmd(0,"MOVE",Map.of("x",Double.NaN,"y",200,"mode","WALK")).accepted());assertFalse(cmd(0,"MOVE",Map.of("x",9000,"y",200,"mode","WALK")).accepted());}
    @Test void treatmentChangesOnlyTargetPart(){var a=e.state.actor(1);double before=a.infection();assertTrue(cmd(1,"HEAL",Map.of("recipient",1,"part","rightArm")).accepted());e.advance(5.1);assertEquals(10,a.body.get("rightArm").infection,.001);assertEquals(0,a.body.get("leftArm").infection);assertTrue(a.infection()<before);assertEquals(3,a.inventory.get("medkit").count);}
    @Test void noInvisibleEnemiesOrOtherPrivateEvidence(){e.state.actor(0).privateEvidence.add("secret_a");e.state.actor(1).privateEvidence.add("secret_b");var v=e.view(0);assertTrue(v.creatures.isEmpty());assertEquals(Set.of("secret_a"),v.actor(0).privateEvidence);assertTrue(v.actor(1).privateEvidence.isEmpty());}
    @Test void isolatedHiveDoesNotSpreadThroughSealedDoors(){e.state.doors.values().stream().filter(d->d.a.equals("B4")||d.b.equals("B4")).forEach(d->d.status=DoorStatus.SEALED);double before=e.state.rooms.get("B3").biomass;e.advance(30);assertEquals(before,e.state.rooms.get("B3").biomass);}
    @Test void creatureCannotCrossClosedDoor(){e.state.doors.values().forEach(d->d.status=DoorStatus.CLOSED);var c=e.state.creatures.get(1);double x=c.x,y=c.y;cmd(0,"INTERACT",Map.of("target","A2","action","LURE"));e.advance(20);assertEquals(x,c.x);assertEquals(y,c.y);assertEquals(100,e.state.actor(0).hp);}
    @Test void LinaChoicesHaveDifferentPersistentConsequences(){e.state.cycle=2;e.advance(60);vote("lina_quarantine","lina_quarantine","lina_refuse");assertTrue(e.state.flags.contains("lina_safe"));assertEquals(5,e.state.supplies.get("filters"));assertEquals("QUARANTINE",e.state.npcs.get("lina").condition);assertEquals(0,e.state.rooms.get("A2").biomass,.01);}
    @Test void saveRoundTripAndTamperDetection(@TempDir Path dir)throws Exception{e.advance(12);var file=dir.resolve("кампания.json");SaveStore.save(file,e.state);var loaded=SaveStore.load(file);assertEquals(e.state.gameTime,loaded.gameTime);assertEquals(e.state.rooms.get("B4").biomass,loaded.rooms.get("B4").biomass);assertEquals(e.state.actor(1).body.get("rightArm").infection,loaded.actor(1).body.get("rightArm").infection);Files.writeString(file,Files.readString(file).replace("МЕДБЛОК","ПОДМЕНА"));assertThrows(java.io.IOException.class,()->SaveStore.load(file));}
    @Test void deterministicReplay(){var other=new GameEngine(WorldFactory.create("REFERENCE_DEMO"));other.state.campaignId=e.state.campaignId;for(var a:other.state.actors){a.connected=true;a.ready=true;}other.start();e.advance(30);other.advance(30);assertEquals(e.state.rooms.get("B4").biomass,other.state.rooms.get("B4").biomass);assertEquals(e.state.creatures.getFirst().x,other.state.creatures.getFirst().x);}
    @Test void duplicateReceiptSurvivesSave(@TempDir Path dir)throws Exception{var p=new Packet("TRADE","trade-unique",Map.of("recipient",1,"item","battery"));assertTrue(e.command(0,p).accepted());var file=dir.resolve("save.json");SaveStore.save(file,e.state);var loaded=new GameEngine(SaveStore.load(file));assertTrue(loaded.command(0,p).accepted());assertEquals(1,loaded.state.actor(0).inventory.get("battery").count);assertEquals(3,loaded.state.actor(1).inventory.get("battery").count);}
    @Test void queueRunsMovementRepairAndReturn(){e.state.creatures.clear();assertTrue(cmd(0,"QUEUE_ACTIONS",Map.of("actions",List.of(Map.of("type","MOVE","x",232,"y",100,"mode","WALK"),Map.of("type","INTERACT","target","B2","action","REPAIR"),Map.of("type","MOVE","x",245,"y",255,"mode","WALK")))).accepted());e.advance(40);assertTrue(e.state.flags.contains("power_stable"));assertEquals("A2",e.state.actor(0).roomId);assertTrue(e.state.actor(0).queue.isEmpty());assertEquals(10,e.state.supplies.get("parts"));}
    @Test void physicalDroneNeedsOpenDoorAndMovesInTime(){var a=e.state.actor(0);a.roomId="C1";a.x=680;a.y=270;assertFalse(cmd(0,"INTERACT",Map.of("target","C1","action","DRONE")).accepted());e.state.doors.get("D13").status=DoorStatus.OPEN;assertTrue(cmd(0,"INTERACT",Map.of("target","C1","action","DRONE")).accepted());e.advance(15.01);var d=e.state.drones.getFirst();assertEquals("SCOUT",d.state);assertFalse(e.state.flags.contains("lina_scanned"));e.advance(.5);assertTrue(d.x>680);assertFalse(e.state.flags.contains("lina_scanned"));e.advance(10);assertTrue(e.state.flags.contains("lina_scanned"));assertTrue(d.battery<100);assertEquals(5,e.state.supplies.get("batteries"));}
    @Test void malformedCommandIsRejected(){var p=new Packet();p.type="READY";p.id="id";assertFalse(e.command(0,p).accepted());}
    @Test void droneDoesNotUndoNpcDecision(){e.state.creatures.clear();e.state.flags.add("lina_decided");var n=e.state.npcs.get("lina");n.condition="ALLY";n.location="A2";e.state.doors.get("D13").status=DoorStatus.OPEN;var a=e.state.actor(0);a.roomId="C1";a.x=680;a.y=270;assertTrue(cmd(0,"INTERACT",Map.of("target","C1","action","DRONE")).accepted());e.advance(35);assertEquals("ALLY",n.condition);assertEquals("A2",n.location);assertFalse(e.state.flags.contains("lina_scanned"));}
    @Test void poweredOffSensorCannotEmitBiomassAlert(){e.state.rooms.get("B3").powered=false;e.advance(20);assertFalse(e.state.triggeredEvents.contains("biomass_alert"));e.state.rooms.get("B3").powered=true;e.advance(1);assertTrue(e.state.triggeredEvents.contains("biomass_alert"));}
}
